# ==============================================================================# 031_SERVICE_DISCOVERY.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS services(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    service_name TEXT,    module TEXT,    category TEXT,    status TEXT,    version TEXT)""")conn.commit()SERVICES = [("BOOT","001_BOOT.py","CORE","ONLINE","1.0.0"),("KERNEL","002_KERNEL.py","CORE","ONLINE","1.0.0"),("EVENT BUS","003_EVENT_BUS.py","CORE","ONLINE","1.0.0"),("DATABASE","004_DATABASE.py","DATABASE","ONLINE","1.0.0"),("LOG ENGINE","005_LOG_ENGINE.py","LOG","ONLINE","1.0.0"),("CONFIG","006_CONFIGURATION_ENGINE.py","CONFIG","ONLINE","1.0.0"),("SERVICE REGISTRY","007_SERVICE_REGISTRY.py","CORE","ONLINE","1.0.0"),("SERVICE MANAGER","008_SERVICE_MANAGER.py","CORE","ONLINE","1.0.0"),("HEALTH CHECK","009_HEALTH_CHECK.py","CORE","ONLINE","1.0.0"),("MAESTRO","010_MAESTRO_CORE.py","AI","ONLINE","1.0.0"),("MISSION ENGINE","011_MISSION_ENGINE.py","MISSION","ONLINE","1.0.0"),("API CORE","013_API_CORE.py","API","ONLINE","1.0.0"),("API ROUTER","014_API_ROUTER.py","API","ONLINE","1.0.0"),("API SERVER","015_API_SERVER.py","API","ONLINE","1.0.0"),("EVENT ENGINE","017_EVENT_ENGINE.py","EVENT","ONLINE","1.0.0"),("OBSERVABILITY","019_OBSERVABILITY_ENGINE.py","OBSERVABILITY","ONLINE","1.0.0"),("METRICS","020_METRICS_ENGINE.py","METRICS","ONLINE","1.0.0"),("SECURITY","021_SECURITY_ENGINE.py","SECURITY","ONLINE","1.0.0"),("AUTH","022_AUTH_ENGINE.py","SECURITY","ONLINE","1.0.0"),("SESSION","023_SESSION_ENGINE.py","SECURITY","ONLINE","1.0.0"),("PERMISSION","024_PERMISSION_ENGINE.py","SECURITY","ONLINE","1.0.0"),("USER","025_USER_MANAGER.py","SECURITY","ONLINE","1.0.0"),("ROLE","026_ROLE_MANAGER.py","SECURITY","ONLINE","1.0.0"),("AUDIT","027_AUDIT_ENGINE.py","AUDIT","ONLINE","1.0.0"),("NOTIFICATION","028_NOTIFICATION_ENGINE.py","NOTIFICATION","ONLINE","1.0.0"),("SETTINGS","029_SETTINGS_ENGINE.py","CONFIG","ONLINE","1.0.0"),("PLUGIN","030_PLUGIN_ENGINE.py","PLUGIN","ONLINE","1.0.0")]for service,module,category,status,version in SERVICES:    cur.execute(        "SELECT id FROM services WHERE service_name=?",        (service,)    )    if cur.fetchone() is None:        cur.execute("""        INSERT INTO services(            created_at,            service_name,            module,            category,            status,            version        )        VALUES(?,?,?,?,?,?)        """,(            datetime.now().isoformat(),            service,            module,            category,            status,            version        ))conn.commit()cur.execute("""SELECTservice_name,category,statusFROM servicesORDER BY service_name""")print("="*80)print("SERVICE DISCOVERY")print("="*80)for row in cur.fetchall():    print(        f"{row['service_name']:<22}"        f"{row['category']:<18}"        f"{row['status']}"    )print("="*80)conn.close()

